import{_ as t,H as a,f as i,i as l}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"热点解读 | 练习课：GPT、市场和我，究竟何去何从？","description":"","frontmatter":{},"headers":[{"level":2,"title":"关于背景：缘何爆火？","slug":"关于背景-缘何爆火","link":"#关于背景-缘何爆火","children":[{"level":3,"title":"Q1：ChatGPT 为什么会这么火？","slug":"q1-chatgpt-为什么会这么火","link":"#q1-chatgpt-为什么会这么火","children":[]}]},{"level":2,"title":"关于“市场”：如何理解投资风向？创业吗？","slug":"关于-市场-如何理解投资风向-创业吗","link":"#关于-市场-如何理解投资风向-创业吗","children":[{"level":3,"title":"Q1：为什么国内各大厂都在 All in GPT?","slug":"q1-为什么国内各大厂都在-all-in-gpt","link":"#q1-为什么国内各大厂都在-all-in-gpt","children":[]},{"level":3,"title":"Q2：怎么看 ChatGPT 对各种领域的影响？","slug":"q2-怎么看-chatgpt-对各种领域的影响","link":"#q2-怎么看-chatgpt-对各种领域的影响","children":[]},{"level":3,"title":"Q3：AGI 创业这一波往哪里走？","slug":"q3-agi-创业这一波往哪里走","link":"#q3-agi-创业这一波往哪里走","children":[]}]},{"level":2,"title":"关于“我”：如何与 AI、AGI 相处？","slug":"关于-我-如何与-ai、agi-相处","link":"#关于-我-如何与-ai、agi-相处","children":[{"level":3,"title":"Q1：我们如何与 AI 相处？","slug":"q1-我们如何与-ai-相处","link":"#q1-我们如何与-ai-相处","children":[]},{"level":3,"title":"Q2：个人如何抓住 AGI 这一波浪潮？","slug":"q2-个人如何抓住-agi-这一波浪潮","link":"#q2-个人如何抓住-agi-这一波浪潮","children":[]},{"level":3,"title":"Q3：“我”好焦虑，ChatGPT 会不会替代自己？","slug":"q3-我-好焦虑-chatgpt-会不会替代自己","link":"#q3-我-好焦虑-chatgpt-会不会替代自己","children":[]}]},{"level":2,"title":"闲话：为什么各国律法对于 AGI 领域约束很强？","slug":"闲话-为什么各国律法对于-agi-领域约束很强","link":"#闲话-为什么各国律法对于-agi-领域约束很强","children":[]},{"level":2,"title":"余热未消","slug":"余热未消","link":"#余热未消","children":[]},{"level":2,"title":"延伸阅读","slug":"延伸阅读","link":"#延伸阅读","children":[]}],"relativePath":"商业思维案例笔记/热点解读｜练习课：GPT、市场和我，究竟何去何从？.md","filePath":"商业思维案例笔记/热点解读｜练习课：GPT、市场和我，究竟何去何从？.md","lastUpdated":1795554691000}'),E={name:"商业思维案例笔记/热点解读｜练习课：GPT、市场和我，究竟何去何从？.md"};function p(n,e,s,h,o,A){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="热点解读-练习课-gpt、市场和我-究竟何去何从" tabindex="-1">热点解读 | 练习课：GPT、市场和我，究竟何去何从？ <a class="header-anchor" href="#热点解读-练习课-gpt、市场和我-究竟何去何从" aria-label="Permalink to &quot;热点解读 | 练习课：GPT、市场和我，究竟何去何从？&quot;">​</a></h1><p>你好，我是雄峰。</p><p>这一次久违的“热点系列”毫无悬念是 ChatGPT 相关的内容。我会从背景、市场、自身的 3 个维度出发，和你聊一聊市场的风向，以及个人如何抓住这一波机会点。</p><p>你可以把这节课当成一节综合复习大课，希望能帮你串联起课程内关于互联网发展逻辑、资本的相关内容。</p><h2 id="关于背景-缘何爆火" tabindex="-1">关于背景：缘何爆火？ <a class="header-anchor" href="#关于背景-缘何爆火" aria-label="Permalink to &quot;关于背景：缘何爆火？&quot;">​</a></h2><h3 id="q1-chatgpt-为什么会这么火" tabindex="-1">Q1：ChatGPT 为什么会这么火？ <a class="header-anchor" href="#q1-chatgpt-为什么会这么火" aria-label="Permalink to &quot;Q1：ChatGPT 为什么会这么火？&quot;">​</a></h3><p>我个人认为有如下两个原因。</p><ol><li>用户的直接体验感受更强。</li></ol><p>过往 AI 领域的代表产品是 2016 年谷歌推出的 AlphaGo，这是大众第一次了解深度学习的威力。但是 AlphaGo 主要在封闭的围棋博弈当中使用，大多数人用不着也体验不上。这就导致大家都知道 AlphaGo 很厉害，但是并没有直观感受。</p><p>相反，ChatGPT 是直接面对 C 端用户使用，聊天体验跟之前的“人工智障”聊天机器人对比非常明显：什么都可以回答，什么都有一定的逻辑性。虽然经常胡说八道，但是也都能够自圆其说，聊起来更像一个中年老男人。</p><ol start="2"><li>文字产品通用面广、适用性高。</li></ol><p>ChatGPT 和 Midjourney 虽然都同样开放给 C 端用户使用，但是 ChatGPT 的出圈程度远比Midjourney 更高。核心在于前者的输出是文字，后者的输出是图片。而文字又属于人类世界底层的基石，人类的一切信息传递和输出都基于文字。</p><p>这就导致文字可以处理的事情远比图片多得多。所以你可以看到有人用 ChatGPT 写作，有人用它整理内容摘要，有人用它查找内容，甚至可以用它来写代码。</p><h2 id="关于-市场-如何理解投资风向-创业吗" tabindex="-1">关于“市场”：如何理解投资风向？创业吗？ <a class="header-anchor" href="#关于-市场-如何理解投资风向-创业吗" aria-label="Permalink to &quot;关于“市场”：如何理解投资风向？创业吗？&quot;">​</a></h2><h3 id="q1-为什么国内各大厂都在-all-in-gpt" tabindex="-1">Q1：为什么国内各大厂都在 All in GPT? <a class="header-anchor" href="#q1-为什么国内各大厂都在-all-in-gpt" aria-label="Permalink to &quot;Q1：为什么国内各大厂都在 All in GPT?&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/1.jpeg" alt=""></a></p><p>因为 GPT 代表的技术要素还在发展，而其他互联网发展的关键要素不再奏效，或者至少没过去奏效。而 GPT 是远比互联网更大的机会。</p><p>这个问题可以从两方面去拆解。一个是推动互联网高速发展的关键要素，一个是这波机会远比互联网要大。先说推动互联网高速发展的关键要素。</p><p>我非常喜欢一句话，“一个人的命运，当然要靠自我奋斗，同时也需要考虑到历史的进程。”实际上，我们每个人都是镶嵌到历史环境当中的，我们需要考虑当前的历史进程是个什么样的情况。为什么我们互联网行业发展的增速慢下来了？这是历史进程的一个大背景或者说环境。</p><p>过去推动互联网高速发展的关键要素是五个：资本、用户、网速、模式、技术。我们来分析一下这五个关键要素如今是什么样的情况，为什么当前已经不再奏效。从而能够倒推为什么现在互联网会慢下来。</p><p>第一，资本。我们简单理解资本，实际上会包含两部分，一个是风投，一个就是企业并购。风险投资实际上是支撑了过往中国互联网乃至世界互联网高速发展最关键的支撑点之一。互联网初期基本上是一个风险博弈型的业务，都需要去募资，从而进行循环式的扩张。另外，大部分时候，互联网公司刚开始是不赚钱的，或者说赚钱业务极少，他就需要去海外募资。风险投资是为了退出的一种投资行为，如果最后卖不出去，砸在手里没有任何获利。但是资本当前没有比较好的退出渠道的，所以也无好的投资方向。再说并购，因为现在的反垄断法存在，也很难进行。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/2.jpeg" alt=""></a></p><p>第二，用户。流量红利见底，我们看两个指标，一个是网络用户的覆盖，一个是网民时长的覆盖。我们的网民应该是有 11-12 亿，实际上微信在 19 年 MAU 就达到了 11 个亿，用户规模在中国已经见底了。网民时长是小马宋提出的概念，以“中国互联网人口 x 每个用户的使用时长”，这就代表了整个流量的一个天花板。前几年，每年涨大概半小时左右，到现在为止，一个用户玩手机的时长可能就是 6 个小时到 7、8 个小时。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/3.png" alt=""></a></p><p>第三，网速。为什么网速也会极大提升了互联网发展？实际上，我们在互联网看的载体不一样，能传输的产品逻辑和用户界面的内容也是不一样的。最开始的时候，几 K 的网络只能传输文本，所以那个时候就是网页。你也根本做不了复杂内容，只能看文字。之后随着宽带加速的出现，你可以在电脑上看到图片。所以那时候会有论坛、贴吧出来。等到了移动互联之后。会有 3G、4G 的出现。实际上，抖音就是 4G 网络最大的一个机会点。网络的进步是能够改变互联网传输介质和交互模式的。但现在 5G 对体验本身没有太大影响，但相反它的费用又会贵很多。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/4.png" alt=""></a></p><p>第四，模式。什么叫模式？我们经常看到电商、B2B、B2C、门户网站、移动支付云计算，都属于模式。基本上，互联网是从美国发展起来的，中国属于引入美国概念，落地在本国。基本上任何新的模式，从国外传递到国内，就会构建出一种新的公司。</p><p>任何一个公司一旦构建起来之后，就会引发一个叫领头羊的角色，明确证明这个模式行业是成立的，既能做大用户规模，又具备生产力提升的空间，从而带动一堆小弟，进入这个行业。</p><p>什么叫生产力提升？</p><p>本质上来说，就是它有没有创造价值。要么极大地降低了成本，要么极大地提升了效率，要么极大地提高了收益，要么极大地提升了体验。而且必须是肉眼可见的提升。如果很多概念循环嵌套，比如 Web3.0、元宇宙，就不是生产力的代表。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/5.png" alt=""></a></p><p>目前来看，没有新的模式出来，但 ChatGPT 明确就是生产力提升的代表，这也是为什么全球都在 All in。现在 AIGC 人工智能领域的发展，它不是属于未来式，它就是一个“ing”形式。以我们公司为例，已经开始裁汰美术了。大量的 3D 美术，大量的 2D 平台美术都在被裁汰，都要统一交给供应商。同时让研发搭 efficient 的框架来解决。</p><p>第五，技术。过往技术的发展也支撑了互联网金融发展，坦白说，这 5 个要素中，现在只有技术还在发展。现在以 AIGC 为代表的人工智能领域又兴起了新一轮的浪潮，来改变我们所有行业。</p><p>至于为什么说这个机会远比互联网更大，这句话可以从 3 个方面去理解。</p><ol><li>互联网有限和局限。</li></ol><p>简单来说，互联网是现实世界在虚拟网络上的镜像。现实世界是由原子（物质世界最小单位）所构成的，互联网是由比特（信息世界最小单位）所构成的，所以美团的创始人王兴也提过，互联网早期就是比特对原子的镜像。</p><p>互联网最大的价值是解决了信息流动的问题。虽然到移动互联网时代也出现了一些以美团外卖/ 滴滴为首的 O2O 业务，互联网开始渗透到了实体行业，但是这些产品只是优化了线下的配对效率，但是本质上对于线下的改造很少。简单总结就是比特优化了原子的效率，但是比特并没有改变任何原子。</p><ol start="2"><li>万物摩尔定律。</li></ol><p>OpenAI 创始人 Sam Altman 一篇自己对于未来趋势理解的文章里提到过：万物摩尔定律，人人富裕的未来。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/6.png" alt=""></a></p><p>他核心的理念在于，人工智能领域也存在类似的摩尔定律，人工智能的成本越往后面价格会越低。如果后面人工智能发展越来越好，成本越来越低，那就可以渗透进生活的方方面面，降低商品和服务的成本。通俗比喻来说，就是建造房子的成本接近于租用机器人的成本，而机器人也是由其他机器人所创造的，那么成本将大幅下降。一个形象的比喻就是：人均一个哆啦 A梦。</p><ol start="3"><li>技术爆炸。</li></ol><p>前几年有一个词很火，叫“吓尿指数”，是说一个人去到多久之后的未来会被吓尿。</p><p>比如康熙突然踏入时空隧道，穿越到了 300 多年后的今天，看到汽车、看到电、看到轮船，大概率会被吓尿。让一个一战的士兵穿越到 100 年后，到今天去参观航空母舰、星际飞船、航天火箭等新式武器，大概率也会被吓尿。</p><p>在接下来的时间里面，吓尿的频率会突然升高，可能几十年，甚至几年的社会发展就能将人吓尿，因为技术的进步实在太快。谁能够在 2012 年的时候可以想象，在 10 年后有 ChatGPT 这样的产品出来？</p><h3 id="q2-怎么看-chatgpt-对各种领域的影响" tabindex="-1">Q2：怎么看 ChatGPT 对各种领域的影响？ <a class="header-anchor" href="#q2-怎么看-chatgpt-对各种领域的影响" aria-label="Permalink to &quot;Q2：怎么看 ChatGPT 对各种领域的影响？&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/7.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/7.jpeg" alt=""></a></p><p>我分析的角度是属于站在应用层，目前已经颠覆了哪些，总结出关键要素。然后去看这可能会影响哪些产业。</p><p>具体做法是，去看 ChatGPT 到底对哪些行业有影响？影响是什么样子的？影响了哪些工作？其他方面是否也会有影响？以及它的影响的底层作用在哪个环节上？是在人上？还是属于是那个技能点上？再或者说是那个业务环节上？它可能还会影响哪些东西？</p><p>举个例子，目前颠覆的，首先插画师这个岗位现在很多人已经凉了。一部分淘宝模特，也已经凉了。之前只是图片，那现在图片跟人可以结合了。这里面典型的就是图片跟人结合的东西。那下一步是不会从 2D 转化到 3D？那这一部分什么行业可能会被影响呢？</p><h3 id="q3-agi-创业这一波往哪里走" tabindex="-1">Q3：AGI 创业这一波往哪里走？ <a class="header-anchor" href="#q3-agi-创业这一波往哪里走" aria-label="Permalink to &quot;Q3：AGI 创业这一波往哪里走？&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/8.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/8.jpeg" alt=""></a></p><ol><li>创业：应用层创业机会更多且成本低。</li></ol><p>现在可以做底层大模型创业的公司寥寥无几，核心在于这个领域极度烧钱。</p><p>举个例子，以坊间信息为例，英伟达中国在 23 年 Q1 就已经完成了全年的收入目标，大量的 GPU 订单排期到了 24 年，现在想要拿到芯片基本上都要年底或者 24 年，且一次性订购都要几百张以上起。H800 芯片一张 10 万，你可以算算这个基础成本有多少？</p><p>这还不算后续搭建服务器以及搭建训练数据的过程，底层大模型创业是一个 10 亿美金以上的生意模式。相反，应用层创业是基于现有业务叠加 AI，核心是找到可商业闭环的应用模式。</p><ol start="2"><li>避坑：应用层创业要远离大模型公司。</li></ol><p>大模型研发费用高昂且相对难赚钱，而应用层通过会员增值即可轻松盈利。很多大模型公司自身也有大量应用层业务，比如国外的微软、谷歌、亚马逊以及 Facebook。国内的阿里、百度、字节以及腾讯，伴随着大模型业务的稳定，这些公司自然也会把触角伸到下游，好比自己开一个商场，哪些店铺生意好，自己也很难动心不去做一个。</p><p>在这个逻辑上，要尽可能避免头部公司强势赛道，或者说错位利用底层大模型能力。比如微软和 openAI 做企业办公工具，那我再进入这个领域，是很难做的。但如果谷歌或者 Facebook的大模型能力成功后，我基于他们的来做企业办公工具，就可以跟微软展开竞争。</p><ol start="3"><li>岗位：应用层创业中，市场和运营更有机会。</li></ol><p>如果产品依托于各家的大模型底层，那么可以做的事情更多在应用层面，这意味这你可以做，他也可以做，大家无非是时间长短的问题。产品同质化较严重的阶段，如何基于运营和市场做差异化，从而找到新的机会点，就是关键。</p><p>当然，这个阶段不可避免也会打价格战，那么融资能力也很关键。而现阶段的融资能力又很关注模式商业闭环。这也是你在做应用层产品的时候需要关注的重点。</p><h2 id="关于-我-如何与-ai、agi-相处" tabindex="-1">关于“我”：如何与 AI、AGI 相处？ <a class="header-anchor" href="#关于-我-如何与-ai、agi-相处" aria-label="Permalink to &quot;关于“我”：如何与 AI、AGI 相处？&quot;">​</a></h2><h3 id="q1-我们如何与-ai-相处" tabindex="-1">Q1：我们如何与 AI 相处？ <a class="header-anchor" href="#q1-我们如何与-ai-相处" aria-label="Permalink to &quot;Q1：我们如何与 AI 相处？&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E7%2583%25AD%25E7%2582%25B9%25E8%25A7%25A3%25E8%25AF%25BB/9.png" alt=""></a></p><ol><li>随时做好失业的准备。</li></ol><p>我们所有人都会面临“被 AI 失业”的过程。过往我们会认为 AI 技术的兴起是优先解决重复性的机械工作，创意类的工作反而很难被取代，而这现在各大游戏公司都在裁撤 2D 平面美术，大量的绘本插画师价格一落千丈。</p><p>这说明一个点，就是过往的判断不一定准确，你永远都无法判断明天和意外哪个先来。因此，做好冗余才是关键。起码自己在失业的过程中有更多的储备可以为下一个阶段做准备。</p><ol start="2"><li>避免陷入 FOMO。</li></ol><p>FOMO，Fear of Missing Out，中文可以叫：错失恐惧症。指的是人们害怕错过任何有趣或重要的事情，以至于经常感到焦虑和不安。这种状态下最大的问题就是容易患得患失，从而被骗。</p><p>我记得之前罗胖说过一句话：你只要说你有病，那一定有人会说我可以治。我经常开玩笑地说，第一波元宇宙赚钱的人是开课的，这一笔 AGI 赚钱的也是开课的，本质上就是利用了大众的焦虑感。</p><ol start="3"><li>做好长期投入的准备。</li></ol><p>目前 AGI 这一波对于大多数人而言都抓不上（这一点我们后面详细展开）。你没看错，即使是大多数从事算法业务的人也抓不上。一方面在于这个领域槽很深，不同算法应用领域不一样，另一方面在于当前处于初期阶段，能往里面冲的人都是做大模型底层的，其尚未往应用层大规模扩展。</p><p>这种状态下，想短期冲一波 AGI 暴富是很难的，而打定主意在这个领域长期投入，不断地寻找新机会，才真的会有新的机会。美团任何一个新业务立项周期是八年，核心在于风险投资的资金回收周期是七年，当资本在行业不起补贴作用的时候，真实的业务机会就会诞生。</p><h3 id="q2-个人如何抓住-agi-这一波浪潮" tabindex="-1">Q2：个人如何抓住 AGI 这一波浪潮？ <a class="header-anchor" href="#q2-个人如何抓住-agi-这一波浪潮" aria-label="Permalink to &quot;Q2：个人如何抓住 AGI 这一波浪潮？&quot;">​</a></h3><ol><li>把 ChatGPT 当成“个人效率杠杆”。</li></ol><p>我们可以把 ChatGPT 作为自己的工具。把它作为我们的信息来源，作为效率提升的工具。前者是能够帮助你获取很多强的信息。后者能够帮助你把很多不错的工作给外包出去，从而让自己时间得到解放。</p><p>这个很简单，就是你需要想办法给他提更多问题，以及让它嵌入到自己的工作流当中。</p><p>举个例子。你每天会有多少问题？你都尝试去问它。有很多数据报表需要整理，你可以尝试问他。有多少邮件需要写，你可以把大概内容写出来，让它帮你写。你就默认成：你要做的事，他是不是就能帮你解决？</p><p>然后再看他更适合做哪些，你更适合做哪些。不是所有东西都交给它，也不一定是只有你做的就是更好的，这里面需要摸索。但是我有点建议，不要用它帮你找数据。因为基本上给的都是一堆错误数据。</p><p>总之，要尽可能让 AI 工具融入自己生活的方方面面，成为 AI 时代的原住民。在 90 年代，会用电脑打字的人就会有一份不错的机会，这句话如今套用在 AI 领域也是一样。</p><ol start="2"><li>把 ChatGPT 当成“个人杠杆”。</li></ol><p>未来的人可以分为会使用 AI 和不会使用 AI 两部分构成，因此要想办法把 AI 变成个人的杠杆工具，就好比现阶段使用 ChatGPT 提升个人工作效率一样。</p><p>你可以看看现在大厂的形势：当你在爬一座山的时候，山在下降。</p><p>实际上，人工智能领域就是这个情况。17 年 Transformer 这个大的框架出来之后，通用大模型领域，跟前一段 AI 领域完全不一样。你在原来领域深耕，会发现还不如在新领域里面随便做的一些东西，立马就能出比之前更好的效果。</p><p>所以，我们一定得去把眼光放在公司外。我们可以在一座山反复爬，没有任何问题。但是得看到，别的山是不是起来得更快。把眼光放到外部，说不定会有更多的场外机会，尤其是这几年。原因很简单，因为 ChatGPT 这一波一定是改变互联网所有生态的新机会。</p><p>但问题是哪些公司有机会呢？</p><p>我自己的感受，在大模型领域，头部公司会更有机会，但是在应用层领域，创新的小公司可能会更有机会。这也是为什么这一波我身边认识的大量的人出来创业做大模型以及做应用层创新。每当新形态诞生，一批新人就会站出来。今天这个机会就是叫 ChatGPT。实际上来说，AI 就这一个是正在崛起的山头，抓住就有弯道超车的机会。</p><ol start="3"><li>“我”应该追风口吗？</li></ol><p>不过现在的形势是，ChatGPT 出来，任何新的东西出来，大家本质上都是做的应用层。你一个星期我两个星期，别人三个星期都能做出来。因为你底层用的是 openAI、stabledisffusion，对不对？底层你没有核心壁垒。你做就是运营，是 SaaS 的工作。我会认为，绝大多数人赶不上 ChatGPT 这一波。</p><p>因为目前用 GPT 有两种变现方式。第一种是你能够足够快地把这里面的信息整理出来，做一个内容，进行包装，这是你基于你的能力去匹配你的目标市场。另外，你也可以基于目标市场，反向去创造你要做的事情点。</p><p>这两种方式都可以，问题点无非就是你必须得快。</p><p>像 ChatGPT，就这一波我看到的大多数赚钱的，很直白说地就是卖知识星球做付费的。这是韭菜，确实是割得快。大量非从业者，把这一块做包装做一个付费。</p><p>但实际上这一块我觉得并不是最关键的，除非是说你能够完整看到你的产业能用 ChatGPT 做很多的改变和动作。</p><p>因为这种模式实际上在前年我们看到过，就是元宇宙。第一波元宇宙赚钱实际上就是做课程的，很便宜，9.9，然后卖出去，我认识的一个做这方面的人，也是 9.9 卖出去的，大概也有个十几万份，很夸张。本身上你是抢风口嘛。</p><p>所以，我认为，ChatGPT 很火，但绝大多数人都赶不上这一波风口。因为你做应用层，实际上是没有核心壁垒的，只是谁做得快的问题而已。</p><p>所以对个人来说，你去追风口，不是不行。问题是你先想清楚追风口，你能不能扛得住？以及从长线来看，你自己能不能抓到这一波的关键。如果你失败呢？那下一步怎么走，要想明白这个点。现在目前这个领域里面追失败的人，一种是本身是做大模型的，是做这块业务领域的。那失败了没关系，还可以去新的公司。</p><h3 id="q3-我-好焦虑-chatgpt-会不会替代自己" tabindex="-1">Q3：“我”好焦虑，ChatGPT 会不会替代自己？ <a class="header-anchor" href="#q3-我-好焦虑-chatgpt-会不会替代自己" aria-label="Permalink to &quot;Q3：“我”好焦虑，ChatGPT 会不会替代自己？&quot;">​</a></h3><p>对程序员来说，可以问问自己，你是所有的时间都在写代码？可能是 20%-30% 的时间是写代码，50% 是在扯需求或者是调试、修 bug，还有 20% 的时间可能是在沟通。</p><p>所以，你会觉得一个代码写完那就完了吗？所以我认为，你可以用 ChatGPT 来辅助你写代码。但本质上，一个好的研发应该是能更好地理解业务需求，能够跟产品把需求对清楚，从而给出很好的指令，能把代码写出来，同时能够调试好代码。</p><p>至于程序员被 ChatGPT 替代的问题。你可以试着想一个点，如果是你自己开公司，你会信任一个程序员写代码，还是信任一个 ChatGPT 写代码呢？</p><p>我是老板，我可能会信任程序员的。为什么呢？一个很现实的问题，因为起码除了做事，我还能追责。如果不出事还好，如果出了事，ChatGPT 能追责任吗？追不了。因为 ChatGPT 一切都还属于黑盒。找研发过来，起码我还能让这位同学帮我修。这是很实际的话题。</p><h2 id="闲话-为什么各国律法对于-agi-领域约束很强" tabindex="-1">闲话：为什么各国律法对于 AGI 领域约束很强？ <a class="header-anchor" href="#闲话-为什么各国律法对于-agi-领域约束很强" aria-label="Permalink to &quot;闲话：为什么各国律法对于 AGI 领域约束很强？&quot;">​</a></h2><p>万物摩尔定律的方向下，可以想象在 AI 的改造下，社会上各个行业都面临着生产力和生产关系的重塑，这种重塑就必然会有大量人员的下岗和淘汰，这种情况也叫技术性失业。</p><p>不同于过往大家认为的“技术性失业只是阶段性的”，比如汽车诞生、马车夫消亡，马车夫可以去学习机车维修相关的工作。越来越多的行业专家认为，很可能这个失业很难有新的机会可以替代上。</p><p>那么，社会上最关键的生产要素会从劳动力转向资本，社会贫富差距会进一步拉大。如果社会资源越来越集中到少数人手里，越来越多的人找不到工作，社会的不稳定性会大大增加，而这种情况势必会影响执政者对于 AGI 领域的看法以及未来政策的制定。</p><p>高盛的研究数据表明：在未来，18% 的岗位会被 AGI 所替代，约有 3 亿全职岗位受到影响。若 AGI 进一步延伸到各行各业，影响范围则会更大。</p><h2 id="余热未消" tabindex="-1">余热未消 <a class="header-anchor" href="#余热未消" aria-label="Permalink to &quot;余热未消&quot;">​</a></h2><p>好了，本期的热点速递到这里就结束了。这次分享的最后，我也给你留了一个问题：对比Web3.0、元宇宙，你能找到它们和 GPT 爆火的相似或者不同之处吗？</p><p>如果你对 GPT 的机会点或者相关内容有更多想要分享的看法，以及更多希望了解的热点信息，也欢迎你在留言区和我互动。</p><p>我们建立了一个读者交流群，欢迎你的加入！如果你觉得有所收获，也可以把这节课分享给你的朋友一起学习。我们下一期热点系列再见！</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><p>一文读懂互联网发展底层逻辑</p><p>资本和补贴推动市场的秘密竟然是……！</p>',114)])])}const g=t(E,[["render",p]]);export{B as __pageData,g as default};
